// The planner deliberately keeps a complete local copy, including for signed-in
// observers.  A telescope site can have no reception: local storage is the
// working copy and the API is a replica when an authenticated connection exists.
//
// There is intentionally one timestamp for the document rather than a timestamp
// generated by the server.  It lets an offline edit win when the device comes
// back online.  `deviceId` makes the origin visible while debugging conflicts;
// it is not an account identifier and never leaves this planner document.
export const plannerSyncVersion = 1;

export const plannerDeviceStorageKey = "astro-portal:planner:device-id:v1";

function timestamp(value) {
  const parsed = Date.parse(value || "");
  return Number.isFinite(parsed) ? parsed : 0;
}

function copy(value) {
  return JSON.parse(JSON.stringify(value));
}

export function plannerDocumentFingerprint(document) {
  const { sync: _sync, ...content } = document || {};
  return JSON.stringify(content);
}

export function plannerDocumentChangedAt(document) {
  return timestamp(document?.sync?.updatedAt);
}

export function plannerDocumentHasContent(document) {
  return Boolean(
    document &&
    ((Array.isArray(document.plans) && document.plans.length) ||
      (Array.isArray(document.knownLocations) &&
        document.knownLocations.length) ||
      (Array.isArray(document.horizonProfiles) &&
        document.horizonProfiles.length)),
  );
}

export function stampPlannerDocument(document, { deviceId, now }) {
  const stamped = copy(document);
  stamped.sync = {
    version: plannerSyncVersion,
    deviceId: String(deviceId),
    updatedAt: new Date(now).toISOString(),
  };
  return stamped;
}

// Returns the complete document to retain.  The two replicas contain the same
// set of plans after the caller writes `winner` to the stale side.  New code has
// a timestamp; the legacy fallback only applies to documents saved before sync
// metadata existed, where recency cannot be reconstructed safely.
export function resolvePlannerDocuments({ local, server }) {
  const localChangedAt = plannerDocumentChangedAt(local);
  const serverChangedAt = plannerDocumentChangedAt(server);
  if (!server) return { winner: local, source: "local", reason: "no-server" };
  if (!local) return { winner: server, source: "server", reason: "no-local" };
  if (localChangedAt > serverChangedAt)
    return { winner: local, source: "local", reason: "newer-local" };
  if (serverChangedAt > localChangedAt)
    return { winner: server, source: "server", reason: "newer-server" };
  if (plannerDocumentHasContent(local) && !plannerDocumentHasContent(server))
    return { winner: local, source: "local", reason: "local-content" };
  // Equal timestamps mean both replicas are already the same sync revision.
  // For old documents without a revision, retain the authenticated copy: it is
  // the only one with a server-side audit trail and avoids deleting it blindly.
  return { winner: server, source: "server", reason: "equal-or-legacy" };
}
